import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"(\d+(?:\.\d+)?|\.\d+)"
_COMPONENT = re.compile(_NUM + r"\s*([A-Za-z]+)")
_ISO_COMPONENT = re.compile(r"(\d+(?:\.\d+)?|\.\d+)([WDHMS])")
_ISO = re.compile(r"P(?:(?:\d+(?:\.\d+)?|\.\d+)W)?(?:(?:\d+(?:\.\d+)?|\.\d+)D)?"
                  r"(?:T(?:(?:\d+(?:\.\d+)?|\.\d+)H)?(?:(?:\d+(?:\.\d+)?|\.\d+)M)?"
                  r"(?:(?:\d+(?:\.\d+)?|\.\d+)S)?)?", re.IGNORECASE)
_ISO_UNITS = {"W": 604800, "D": 86400, "H": 3600, "M": 60, "S": 1}


def _round(total: Decimal) -> int:
    return int(total.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _parse_iso(text: str) -> int:
    upper = text.upper()
    if upper == "P" or upper.endswith("T") or not _ISO.fullmatch(upper):
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    date_part, _, time_part = upper[1:].partition("T")
    total = Decimal(0)
    for part, allowed in ((date_part, "WD"), (time_part, "HMS")):
        pos = 0
        while pos < len(part):
            m = _ISO_COMPONENT.match(part, pos)
            if not m or m.group(2) not in allowed:
                raise ValueError(f"invalid ISO 8601 duration: {text!r}")
            total += Decimal(m.group(1)) * _ISO_UNITS[m.group(2)]
            pos = m.end()
    return _round(total)


def _parse_clock(text: str) -> int:
    fields = text.split(":")
    if len(fields) not in (2, 3):
        raise ValueError(f"invalid clock duration: {text!r}")
    if not all(re.fullmatch(r"\d+(?:\.\d+)?", f) for f in fields):
        raise ValueError(f"invalid clock duration: {text!r}")
    values = [Decimal(f) for f in fields]
    if any(v >= 60 for v in values[1:]):
        raise ValueError(f"invalid clock duration: {text!r}")
    total = Decimal(0)
    for v in values:
        total = total * 60 + v
    return _round(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)

    if s[0] in "Pp":
        return _parse_iso(s)

    if ":" in s:
        return _parse_clock(s)

    total = Decimal(0)
    pos = 0
    while pos < len(s):
        if s[pos].isspace():
            pos += 1
            continue
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += Decimal(m.group(1)) * _UNITS[unit]
        pos = m.end()
    if total == 0 and not re.search(r"\d", s):
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

